#include <d3d8.h>
#include "WW3D2/ShaderClass.h"
#include "WW3D2/w3d_file.h"

// Retail 0x00DB6220 (initial value D3DCULL_CW): the sense of backface culling, shared by every shader.
static unsigned long _PolygonCullMode = D3DCULL_CW;
// FUNCTION: BFME2 0x00137550 size=28 name=?Init_From_Material3@ShaderClass@@QAEXABUW3dMaterial3Struct@@@Z evidence=N:ledger tier=B hypothesis:Z
void ShaderClass::Init_From_Material3(const W3dMaterial3Struct &mat3)
{
	// The three setters are expanded in place by retail (the header's inline forms), so their masks fold into one.
	if (mat3.Attributes & 1) {	// W3DMATERIAL_USE_ALPHA
		ShaderBits = (ShaderBits & ~(unsigned long)MASK_DEPTHMASK) | (DEPTH_WRITE_DISABLE << SHIFT_DEPTHMASK);
		ShaderBits = (ShaderBits & ~(unsigned long)MASK_DSTBLEND) | (DSTBLEND_ONE_MINUS_SRC_ALPHA << SHIFT_DSTBLEND);
		ShaderBits = (ShaderBits & ~(unsigned long)MASK_SRCBLEND) | (SRCBLEND_SRC_ALPHA << SHIFT_SRCBLEND);
	}
}

// FUNCTION: BFME2 0x00137590 size=2840 name=?Apply@ShaderClass@@AAEXXZ evidence=N:ledger tier=B hypothesis:Z

// FUNCTION: BFME2 0x00138110 size=26 name=?Invert_Backface_Culling@ShaderClass@@SAX_N@Z evidence=N:ledger tier=B hypothesis:Z
void ShaderClass::Invert_Backface_Culling(bool onoff)
{
	if (onoff == true) {
		_PolygonCullMode = D3DCULL_CCW;
	} else {
		_PolygonCullMode = D3DCULL_CW;
	}
	Invalidate();
}

// FUNCTION: BFME2 0x00138130 size=126 name=?Get_SS_Category@ShaderClass@@QBE?AW4StaticSortCategoryType@1@XZ evidence=N:ledger tier=B hypothesis:Z
ShaderClass::StaticSortCategoryType ShaderClass::Get_SS_Category(void) const
{
	// category: Opaque
	if ((ALPHATEST_DISABLE == Get_Alpha_Test()) && (DSTBLEND_ZERO == Get_Dst_Blend_Func()))
		return SSCAT_OPAQUE;
	// category: Alpha Test (BFME 2's alpha test field has two enabled values, 1 and 2)
	if ((ALPHATEST_ENABLE == Get_Alpha_Test()) || (2 == (int)Get_Alpha_Test())) {
		if (DSTBLEND_ZERO == Get_Dst_Blend_Func()) return SSCAT_ALPHA_TEST;
		if ((SRCBLEND_SRC_ALPHA == Get_Src_Blend_Func()) &&
			(DSTBLEND_ONE_MINUS_SRC_ALPHA == Get_Dst_Blend_Func()))
			return SSCAT_ALPHA_TEST;
	}
	// category: Additive
	if ((SRCBLEND_ONE == Get_Src_Blend_Func()) && (DSTBLEND_ONE == Get_Dst_Blend_Func()))
		return SSCAT_ADDITIVE;
	// category: Screen
	if ((SRCBLEND_ONE == Get_Src_Blend_Func()) && (DSTBLEND_ONE_MINUS_SRC_COLOR == Get_Dst_Blend_Func()))
		return SSCAT_SCREEN;
	// category: Everything else
	return SSCAT_OTHER;
}


// FUNCTION: BFME2 0x001381B0 size=40 name=?Guess_Sort_Level@ShaderClass@@QBEHXZ evidence=N:ledger tier=B hypothesis:Z
int ShaderClass::Guess_Sort_Level(void) const
{
	int sort_level;
	StaticSortCategoryType scat = Get_SS_Category();

	switch (scat)
	{
	case ShaderClass::SSCAT_OPAQUE:
	case ShaderClass::SSCAT_ALPHA_TEST:
		sort_level = 0;		// SORT_LEVEL_NONE
		break;
	case ShaderClass::SSCAT_SCREEN:
		sort_level = 15;	// SORT_LEVEL_BIN2
		break;
	case ShaderClass::SSCAT_ADDITIVE:
		sort_level = 10;	// SORT_LEVEL_BIN3
		break;
	default:
		sort_level = 20;	// SORT_LEVEL_BIN1
		break;
	}
	return sort_level;
}

// FUNCTION: BFME2 0x001381F0 size=13 name=?Is_Backface_Culling_Inverted@ShaderClass@@SA_NXZ evidence=N:ledger tier=B hypothesis:Z
bool ShaderClass::Is_Backface_Culling_Inverted(void)
{
	return (_PolygonCullMode == D3DCULL_CCW);
}

// FUNCTION: BFME2 0x00138200 size=108 name=?Enable_Fog@ShaderClass@@QAEXPBD@Z evidence=N:ledger tier=B hypothesis:Z
void ShaderClass::Enable_Fog(const char *source)
{
	// Enable the appropriate fog mode based on the shader's source and destination blends (the fog setter is expanded in place).
	switch (Get_Src_Blend_Func()) {

	case ShaderClass::SRCBLEND_ZERO:
		if (Get_Dst_Blend_Func() == ShaderClass::DSTBLEND_SRC_COLOR) {
			ShaderBits = (ShaderBits & ~(unsigned long)MASK_FOG) | (ShaderClass::FOG_WHITE << SHIFT_FOG);
		}
		break;

	case ShaderClass::SRCBLEND_ONE:
		switch (Get_Dst_Blend_Func()) {

		case ShaderClass::DSTBLEND_ZERO:						// Opaque.
			ShaderBits = (ShaderBits & ~(unsigned long)MASK_FOG) | (ShaderClass::FOG_ENABLE << SHIFT_FOG);
			break;

		case ShaderClass::DSTBLEND_ONE:						// Additive.
		case ShaderClass::DSTBLEND_ONE_MINUS_SRC_COLOR:		// Screen.
			ShaderBits = (ShaderBits & ~(unsigned long)MASK_FOG) | (ShaderClass::FOG_SCALE_FRAGMENT << SHIFT_FOG);
			break;

		default:
			break;
		}
		break;

	case ShaderClass::SRCBLEND_SRC_ALPHA:
		if (Get_Dst_Blend_Func() == ShaderClass::DSTBLEND_ONE_MINUS_SRC_ALPHA) {
			ShaderBits = (ShaderBits & ~(unsigned long)MASK_FOG) | (ShaderClass::FOG_ENABLE << SHIFT_FOG);
		}
		break;

	case ShaderClass::SRCBLEND_ONE_MINUS_SRC_ALPHA:
		if (Get_Dst_Blend_Func() == ShaderClass::DSTBLEND_SRC_ALPHA) {
			ShaderBits = (ShaderBits & ~(unsigned long)MASK_FOG) | (ShaderClass::FOG_ENABLE << SHIFT_FOG);
		}
		break;
	}
}

